import{_ as a,b as l,a as i,aS as e}from"./chunks/framework.M2Whok06.js";const q=JSON.parse('{"title":"伟大的毛主席","description":"","frontmatter":{},"headers":[],"relativePath":"note/history/modern-chinese-history/教员.md","filePath":"note/history/modern-chinese-history/教员.md","lastUpdated":1736084727000}'),t={name:"note/history/modern-chinese-history/教员.md"},r=e(`<h1 id="伟大的毛主席" tabindex="-1">伟大的毛主席 <a class="header-anchor" href="#伟大的毛主席" aria-label="Permalink to &quot;伟大的毛主席&quot;">​</a></h1><div class="tip custom-block github-alert"><p class="custom-block-title">中国上下五千年千古第一人，中国历史上第一个喊出“人民万岁”的伟大领袖</p><p></p><p>麦子熟了千万次,人民万岁第一次</p><p>小时候在大人的教育下崇拜您，少年时在敌人的忽悠下怀疑您，长大后在自己的探索中敬佩您</p><p>崇拜您 质疑您 理解您 怀念您 成为您 超越您</p></div><h2 id="个人简介" tabindex="-1">个人简介 <a class="header-anchor" href="#个人简介" aria-label="Permalink to &quot;个人简介&quot;">​</a></h2><p>毛泽东（1893年12月26日-1976年9月9日），字润之，笔名子任，湖南湘潭人。<br> 伟大的马克思主义者，中央军委主席，中国人民领袖，中国共产党员， 无产阶级革命家，政治家，理论家，军事家，战略家。<br> 毕业院校：湖南省立第一师范学校<br> 代表作品: 矛盾论、实践论、论持久战</p><h2 id="教员的重大转折" tabindex="-1">教员的重大转折 <a class="header-anchor" href="#教员的重大转折" aria-label="Permalink to &quot;教员的重大转折&quot;">​</a></h2><p>伟人自己曾经说过 ，我从1927年到1935年 ，基本上是受压的 ，在党内没有发言权 ，只是到了1935年的 ，遵义会议后 ，才慢慢地好起来。</p><h3 id="第一次打击" tabindex="-1">第一次打击 <a class="header-anchor" href="#第一次打击" aria-label="Permalink to &quot;第一次打击&quot;">​</a></h3><p>1927年9月9日，当时还是中央政治局候补委员的伟人奉命领导秋收起义，按共产国际要求的“城市中心论” 攻打长沙，但因为敌人的力量太强大了，起义很快失败了。 9月19日，秋收起义的部队，在文家市会师。伟人根据敌我力量的实际对比，决定放弃攻打长沙，带领不足千人的队伍来到了井冈山，开辟了中国共产党第一个革命根据地。 伟人说，我们当时的力量还太小啊。还不能去攻打敌人重兵把守的大城市，应当先到敌人统治薄弱的农村去保存力量，发动农民革命。 我们现在好比一块小石头，蒋介石反动派好比一口大水缸，但总有一天我们这块小石头。一定会打烂蒋介石那口大水缸，胜利一定属于我们。 现在我们看这件事儿好像没做错吧？成功开辟革命根据地，这应该是大功绩吧？但伟人率兵退到井冈山之后，上海的中央和共产国际是闻讯震怒。 1927年11月9日，在共产国际代表罗米那兹的领导下，瞿秋白在上海主持召开中国中央临时政治局扩大会议。会议强调，中国的革命形势在不断高涨， 中国革命性质是不断革命。湖南省委在秋收起义的战略方针上完全违背中央策略，对此，毛泽东应该负严重的责任， 应予开除中央临时政治局候补委员，并撤销其湖南省委委员身份。对于毛泽东在文家市决定转兵前往井冈山，放弃攻打大城市的行为。 共产国际代表和中共中央定义为可说是最可耻的背叛与临阵脱逃。这个定义可以说是很严重的，当时也没有电台，信息传达也不畅通， 湖南省委的组织遭到了敌人极度严重的破坏。因此，这个命令传达到井冈山的时候，已经是1928年3月了。 由湖南特委军事部长、省军委特派员、20多岁的周鲁上井冈山传达。当时白色恐怖严重，不能带文件，只能凭记忆传达。年轻的周鲁传达上级指示时呢， 只记得开除，但开除什么记不清了。就想当然的说成是开除党籍。开除党籍这是比开除中央临时政治局后补委员严重无数倍的惩罚呀， 等同于政治生命的终结。井冈山上所有人都不明白为什么伟人要遭受这么严重的惩罚。他老人家自己呢，更是无法理解，大口大口的吸自己用纸卷的大炮筒烟， 自己带着残兵上了井冈山。而且打了很多胜仗，硬生生的从不足1000人不满一个团的兵力，发展成了一个师，两个团，还在三个县建立了稳定的工农政权， 把革命根据地搞的风生水起，蓬勃发展。这个时候，自己突然遭受到了如此严重的惩罚。到底上哪儿说理去？但是我们的伟人没有怨言，面对如此重大的冤屈， 依然是面不改色。被开除党籍以后，伟人不能担任书记和党代表，不能过党组织生活，那他该干什么去面对这个询问？周鲁说，你改任师长吧， 当时军事干部是可以不是党员的。于是毛泽东改任工农革命军第一师师长，对于党中央的决议完全不能理解， 但一个20岁的周鲁传达的指示还是错误记忆的指示。伟人立刻就无条件的遵守了，还是在一个完全由自己创立的地盘儿。 1928年4月中旬，伟人率领工农革命第一师策应湘南暴动期间，在湘南特委机关见到了中共中央政治纪律决议案的正式文件。上面明文写着， 仅仅是被中央开除中央临时政治局候补委员和撤销湖南省委委员，但根本就没有开除党籍的决定。伟人这才大大的松了一口气，不管怎么说，他还是党员嘛。 只是被开除了几个重要的职位而已。1928年4月底，朱毛会师井冈山，随后合二为一，成立了工农革命第四军。朱德任军长，伟人任党代表，陈毅任教导大队大队长。 随后，委人当选为第四军的军委书记，率领第四军连续粉碎了敌人的两次围剿、三次围剿，并在1929年初打下了井冈山，开辟了赣南、闽西革命根据地。 中央对伟人的处分始终没有撤销掉，仅仅保留了党员这一身份，但伟人凭借自己的努力，一点一点的在战场重新又打回自己的威望。这是伟人第一次蒙冤受屈。</p><h3 id="第二次打击" tabindex="-1">第二次打击 <a class="header-anchor" href="#第二次打击" aria-label="Permalink to &quot;第二次打击&quot;">​</a></h3><p>教员的第二次蒙冤是1929年5月，开辟赣南、闽西革命根据地以后不久。教员在坚持党对军队的绝对领导这一问题上，和朱德、陈毅等人发生了分歧。 军队指挥由谁说了算？教员说，应该由党说了算。而且是绝对领导，不容置疑。这一原则有问题吗？没有问题，但当时的党代表是教员， 而军长朱德等人认为是具体打仗的事儿，应该由军人说了算。外行不能指导内行。1929年6月22日，红四军第七次代表大会在龙岩城召开。由陈毅主持会议。 在会议上，代表们围绕着井冈山斗争以来遇到的各方面问题进行了讨论，对教员的民主作风和工作方法予以批评。 根据陈毅的回忆录，当时对教员的批评主要由四点组成。第一。批评伟人对马列主义的信仰不够，因为他常讲马列主义只规定了世界革命、中国革命的基本原则。 但中国革命具体做法还要我们自己在实际之间来创造。第二，批评伟人有个人英雄主义，他讲的现在革命没有党的领导一定失败。 这话实际上是说没有你毛泽东就要失败。第三，批评毛泽东的领导方式是家长式的领导。你们朱毛两人天天在吵架，一个是晋国，一个是楚国，你们两个大国天天吵， 我们这个郑国在中间简直是不好办。两大之间难为小。第四批评毛泽东说没有调查就没有发言权是不对的，共产党都应该有发言权。说错了可以改正吗。 会议还否定了教员提出来的党对红军领导必须实行集权制的意见，并给予教员党内严重警告处分。同时，教员前敌委员会书记的身份被陈毅所取代。 这是他老人家一生中唯一的一次被下级夺了权，7月中旬，教员被迫离开了红四军以特派员的身份到闽西指导地方工作， 离开了军队一线和教员随行的江华在回忆录中写道，我们离开部队，由龙岩出发时，把我的马也扣下了，那时我们一行人真有些灰溜溜的样子。 离开龙岩以后，教员大病了一场，患的是疟疾，浑身时冷时热，时好时坏，只得化妆成教书先生，在永定的深山中隐蔽起来，在此治病和工作。 9月下旬，红四军第八次党代表大会。在上杭召开致信，要求在永定县的教员参加，教员说自己身体有病，不能参加。红四军党委认为教员在闹情绪，托辞不来， 于是立即再次给予教员严重警告，要他马上来开会。于是，教员强撑着病体坐担架赶来。大家看到教员面无人色，确实病重，就让他留在上杭继续养病。 所有人都没有想到，革命根据地的开辟者被夺了权，并被赶出了军队，居然一点儿脾气都没有。不来开会的原因，竟然真的是在有病，而且是重病。 1929年7月9日，陈毅以前委书记的名义讲胡四军第七次党代表大会。决议案和党内争论文件送交党中央。1929年8月10日，中央收到了这份文件。 1929年8月13日，中央召开政治局会议进行讨论。会议决定充分肯定了教员提出的工农武装割据重要思想。和党对军队的绝对领导这一军队建设基本原则。 1929年11月，红四军吃了大败仗，损失了接近1/3的兵力。中央做出指示，恢复教员的工作。1929年11月26日，教员恢复工作。 1929年12月28日，红四军第九次党代表大会在古田召开。古田会议会议决定，将党对军队的绝对领导权这一原则作为自己建军思想。 古田会议决议成为了日后红军建设的纲领性文件，为中国人民解放军的政治工作奠定了基础。同时，古田会议决定选举委员为红四军前委书记，拥有对红四军的最高领导权。 这是教员一生中第二次的蒙冤受屈。</p><h3 id="第三次打击" tabindex="-1">第三次打击 <a class="header-anchor" href="#第三次打击" aria-label="Permalink to &quot;第三次打击&quot;">​</a></h3><p>第三次蒙冤是在古田会议以后，红四军纵横驰骋，进一步发展赣南、闽西革命根据地。进一步扩大红军队。 1930年6月，红四军被改编为红一军团，而赣南、闽西革命根据地也最终被发展成了中央苏区。1930年10月，蒋介石在结束中原大战以后，集中10万大军进攻中央苏区。 教员率领红一方面军歼敌1.3万人，活捉了张辉瓒，打破了国民党第一次围剿，并写下了那首著名的渔家傲来抒发自己的万丈雄心。 1931年4月，蒋介石集中20万军队，以何应钦为总指挥，采用稳扎稳打、铁壁合围的方针，对中央红军进行围剿。教练率领红一方面军，采用诱敌深入的方针， 将3万多兵力全部集中在一个点，在15天内连续打了5次胜仗，歼灭敌军3万多人，打破了国民党的第二次围剿。1931年7月，蒋介石亲任总司令，集中了30万兵力， 并聘请了德、日。英军事参谋，采取分路围攻，长驱直入的战术，分三路向中央苏区进行围剿。教员率领红一方面军采用一七主力打击虚弱的作战方针， 抓住机会，后来在4天内三战三捷。休整半个月以后，再次三战三捷，在80天内歼灭敌军3万多人，粉碎了国民党的第三次围剿。 三次反围剿的胜利，中央苏区不断扩大，已经发展到了28个县，拥有了250万人口。中央红军呢，也不断强盛，很显然，教员立下了大功， 是不是应该重奖呢？因为中央苏区的辉煌成绩。巨大的地盘儿和最强的兵力。在上海的临时，中央决定把中央苏区当成核心红区，但极其反感教员的游击思想。 1931年11月初，中共中央代表团在瑞金主持召开中央苏区党组织第一次代表大会。史称赣南会议。 会议从思想、政治、军事和组织四个方面全方位的否定教员的路线和政策。教员制定的建设根据地的正确主张，被斥责为非无产阶级观点，单纯防御和游击主义。 狭隘经验主义等等。在会议上，博古也就是秦邦宪对教员说，你懂什么马列理论，简直就是一个乡巴佬。 最终会议决定设立中央革命军事委员会，取消了老人家红一方面军总司令和总政委、总前委书记的职位，撤销了教员苏区中央局代理书记的职位。体面的把军权从教员手里收走了。</p><p>赣南会议取消了老人家红一方面军总司令和总政委、总前委书记的职位，撤销了教员苏区中央局代理书记的职位，体面的把军权从教员的手中收走了。 最后，王明左倾冒险主义在整个儿根据地进行推广，但教员在中央苏区的威望实在是太大了。1931年11月7日，中华苏维埃第一次全国代表大会在江西瑞金召开， 教员直接当选了中央执行委员会主席。人民委员会主席、中华苏维埃共和国临时中央政府主席，这是教员第一次被人称之为主席， 但主席的这个称呼没有持续太久。一山不容二虎，中央苏区到底是听主席的，还是听王明的？冲突很快就出现了，1932年1月，中央决定攻打赣州， 执行共产国际攻占大城市的指令，让中国革命大踏步步的走向胜利。但是 教员是强烈反对的，认为赣州铜墙铁壁，根本不可能打的下来。于是中央免除了教员、中央局代理书记一职，红一军团兵进赣州，围了赣州很久，实在是打不动。 马上，中央红军就要被国民党军队包围了。1932年3~4月，在周恩来的邀请下，教员重整局面，带领红军撤围赣州，跳出了包围圈儿，并出其不意的发动了漳州战役， 攻克漳州城。歼灭国民党军第49师大部，俘虏了副旅长以下1674人，缴获各种枪支2140支，各种炮6门，飞机2架，同时收缴了百万银元，扩军上千，取得了巨大胜利。 这个战果是不是应该给我们的教员颁个奖？当然不应该，因为你撤回了江西核心城市赣州，而且继续反对攻打中心城市，打了个漳州有啥用啊？那是大城市吗？ 都这么慢腾腾的搞，中国革命什么时候才能胜利呀。1932年10月，王明领导的中央政治局在宁都召开了中共苏区中央局全体会议，史称宁都会议， 集中火力批评教员。会议要求红军以。进攻战略直接粉碎敌人的进攻，以夺取中心城市为主要作战目的，指责教员提出的诱敌深入是专门去等待敌人进攻的右倾主要危险， 批评教员主张向赣东北方向农村发展的主张是消极怠工。对教员批评苏区中央急于进攻中心城市的行为，定义为不尊重党领导机关。 会议以后，教员再次被撤销了几乎一切职务，被调到了后方去养病，完全丧失了党权、军权，变成了一个无职无权的。普通一兵， 包括邓小平在内的一些支持教员路线的高级领导人也被撤职批判。从这一天开始，教员被雪藏整整3年多时间。 教员在延安时曾轻描淡写的说，我在瑞金的中央苏区过了四年小媳妇儿日子。教员还曾经这么说过，一些吃过羊面包的人不信任我， 认为山沟子里出不了马克思主义。1932年秋开始，我没有工作。就从漳州以及其他地方儿搜集过来的书籍中，把有关马列恩斯的书通通找了出来， 不全不够的就向一些同志借。我就埋头读马列著作，差不多整天看，读了这本儿，又看那本儿，有时还交替着看。扎扎实实下功夫，硬是读了两年书。 他们把我这个木菩萨进到粪坑里，再拿出来，搞得臭的很。那时候儿，不但一个人也不上门儿，连一个鬼都不上门儿。 我的任务是吃饭、睡觉和拉屎，还好我的脑袋没有被砍掉。陈毅曾经这么回忆说。 伟人是一个受过侮辱、冤枉和虐待的人，他被撤过职，受过党内的审查，被宣布为机会主义者蒙受 耻辱被送往后方休养，没有人去看望他，因为谁也不敢接近他。伟人立下了如此巨大的功勋，结果却蒙受了如此巨大的冤屈， 被几个到苏联留过学的20多岁的小娃娃给直接一撸到底。如果换成我们，我们会怎么做？会因此愤怒，因此对党失望，因此怀恨在心吗？ 普通人也许什么想法儿都会有，但教员就是教员，他依然选择了无条件接受党的一切命令。被一撸到底，我就看书学习，坚持原则，顾全大局，遵守纪律。 尽可能的在力所能及的范围内做出自己的贡献，绝不消极沉沦。周恩来回忆说，在撤销红军总政委的职务以后，伟人对他说需要我的时候儿打个招呼。 没有多久，赣州打不下来了，项英去请他，他二话没说就去了，还帮助解决了困境，在第五次反围剿中，他连献三计破围，虽然被置之不理，但他没有把自己置身事外， 始终心系党和军队。 当时许多会议都不让他参加，但是他的态度是，只要让他参加，他就一定出席，去了就在会议上宣传他的观点，不管人家喜欢不喜欢听。 教员退出领导岗位以后，王明、博古等人终于可以毫无阻碍的全盘照搬苏联的政治体制和意识形态，按照苏联红军的形态去改造中央红军了。 然后中央红军在王明博古等人的领导下寸寸不让。处处设防，节节抵御，大搞短促突击，和国民党军正面对抗，结果一败再败， 中央红军损失惨重，只剩余86000余人，关键的战略位置几乎都被国民党给占据，生存空间被严重挤压。 到1934年11月10日，中央红军被迫长征，教员生病，是躺在担架上参加长征的。1934年12月3日，红军渡过了湘江，突破四道封锁线，但损失极为惨重，仅剩下3万多人。 马上快全军覆没，教练在领导岗位的时候儿屡战屡胜，越打越强，而全面否定教员的思想以后就吃了如此之大的败仗，谁对谁错已经非常明显了， 要不要立刻把教员请回来主持大局呢？</p><h3 id="遵义会议" tabindex="-1">遵义会议 <a class="header-anchor" href="#遵义会议" aria-label="Permalink to &quot;遵义会议&quot;">​</a></h3><p>周恩来曾在一个青年会议上讲如何学习伟人思想，他说，当他的意见没有被大家接受时，他就等待，有机会他就讲。 又教育说服我们不要主张打大城市，他认为我们力量小，不应该打大城市，应该集中力量建设根据地。但是他的意见大多数人不赞成，大家要打，他只好跟着打。 后来打败了，他赶快在会议上提出。打败了，证明这个方法不行，换一换，大家还是不接受，他只好再等待，又跟着大家走，正确的认识、 意见要经过许多等待、迂回才能取得胜利，被大家所接受。在代价极其惨重的连续失败面前，原本。支持左倾冒险路线的王家祥、张闻天等人和博古、李德产生了严重分歧， 生病的教员和负伤的王家祥在担架上聊天儿，然后又上门做张闻天的思想工作，探讨如何才能让红军更好的走向胜利。反复多次以后， 教员争取到了王家祥和张闻天的理解和支持，而这样的聊天，教员进行了一次又一次，把能聊的人都聊了，争取到了越来越多的人。 支持他对自己思想的不懈宣传。这样的事儿，教员已经做了3年多，一直没有任何效果。但这一次，教员的努力终于得到了回报。 由于条件极其困难，此时中央红军和共产国际的无线电联系中断了。远在苏联的王明无法对中央遥控指挥。得到王家祥和张闻天的指示以后， 教员在1934年12月12日参加了通道会议。在会议上，教员提出部队必须向其进入贵州，并阐述了自己的理由。 得到了大多数人的支持，1934年12月18日召开了黎平会议，改变了博古制定的挺进湘西北计划，按照教员的意见，改向黔北进军， 准备创建以遵义为中心的川黔边根据地为。重新制定了新的战略方针，1935年1月1日召开了猴场会议，否定了李德个人包办军事指挥权的情况。这三个会议的召开。 为遵义会议奠定了基础，1935年1月15日到17日，挽救党、挽救红军、挽救中央革命的遵义会议召开， 用三天的时间集体大辩论，讨论第五次反围剿失败的主要原因。在这次会议上。博古认为失败的主要原因是敌人过于强大，和指挥没关系。 周恩来认为自己对失败应当承担责任进行自我批评，并批评了博古和李德。教员做了长篇发言，系统性的指出了博古和李德。在军事指挥上的种种错误。 王稼祥的发言除批判了博古和李德以外，还建议取消博古和李德的军事指挥权，把红军交给教员这样富有经验的人来指挥。张闻天对王家祥的意见表示支持。 刘伯承说，没有本钱打什么洋仗，教员是有什么本钱打什么仗？朱德说，丢掉了根据地，牺牲了多少人民。如果继续这样领导，</p><p>我们就不可能再跟着走下去了，李富春、聂荣臻、彭德怀等人的发言也都很激烈，大家都对博古和李德的错误指挥非常不满，在会议上，教员得到了绝大多数人的支持。 和博古、李德共同组成中央三人团的周恩来最后也表态，全力推举教员来领导。 至此，以教员为首的新一代党中央领导集体确立了。中国革命避免了失败的命运，越过了转折点， 开始走向了辉煌的征程。遵义会议以后，教员为首的新一代党中央领导集体确立中国革命，避免了失败的命运，越过转折点，开始走上了辉煌的征程。 你是不是认为故事到这儿就讲完了？别急，还有，在遵义会议拿到指挥权以后，所有人都无条件的服从教员的指令。教员就可以一心一意的和蒋介石做斗争了？ 当然不是。1935年3月10日遵义会议召开仅仅两个月以后，军委开会对林彪关于进攻打鼓新场的提议进行讨论， 召开了苟坝会议，打鼓新场是通往黔西的必经之地，如果能够攻占，那么对红军西进极为有利，而且看起来守军也不多。在会上。大多数人都认为可以进攻打鼓新场， 代价不大，好处多多，但教员却认为打鼓新场位置重要，周围有蒋介石多股部队，红军进攻此处有被包围的可能性。几份被破译的电报也表明， 黔军、滇军有向打鼓新场附近移动的征兆，红军不应该冒险，教员把自己的想法儿，证据也都展示，但大家都表示他多虑了， 最后举手表决，包括朱德、周恩来、张闻天在内的20多个人都支持进攻打鼓新场，只有教员一个人反对，投票结果是完全的碾压。教员急眼了， 他认为此事关乎红军的生死存亡。自己绝不能退，教员真来了脾气，对主持会议的张闻天说，你们硬要打我，就不当这个前敌司令部政委了。 一向支持李德的凯丰当场顶的教员少数服众多数，你这是什么态度？张闻天则说。不干就不干吧。最后会议形成了进攻打鼓新场的决议，同时免去了教员的前敌司令部政委职务 。散了会以后，教员在床上辗转反侧，无法入睡，最后决定去找周恩来，周恩来这样回忆说。他回去一想，还是不放心，觉得这样不行啊。 半夜里提着马灯又到了我那里，叫我把命令晚一点儿发，还是想一想，我接受了他的意见，一早再开会议，把大家都说服了。</p><p>打鼓新场一战，朱德、周恩来、张闻天在内的20多个人都支持进攻，只有教员一个人反对，但张闻天带头儿举手表决，否定了老人家的观点，气得老人家撂了挑子。 但老人家呢，经过一晚上的商量，还是说服了周恩来和朱德。3月11日，苟坝会议继续召开。周恩来和朱德在会议上赞同教员的看法， 讲形式，立陈利弊，最后其他人也从善如流，接受了这一观点。会议恢复了教员的中央红军前敌司令部政委职务，并决定。朱德的名义发出关于我军不进攻打鼓新场的指令， 就在这份儿指令发出去的同时，仅仅几个小时以后，我军就侦查到滇军孙渡部已经向打鼓新场进发。而川军郭勋祺部、周浑元部、吴奇伟部。正围绕打鼓新场进行活动， 以8个师的绝对优势兵力，形成了对打鼓新场的合围战略姿态。这份情报传回了红军总部以后，所有人都吓出了一身冷汗。</p><p>稍有不慎，红军就会重演湘江战役的惨烈。蒋介石布下的这个陷阱，参会的20多个领导人都没看出来，其中甚至包括朱德和周恩来， 只有教员一个人强烈反对。教员手上的那一盏昏黄的马灯。在暮色中为红军指明了正确的道路，这件事引发了教员的思索。 军事决议民主制是为了防止博古、李德对军事的专制错误指挥而设定，但目前看来好像并不正确。于是教员向周恩来、张闻天提出。 不能像过去那么多人集体指挥军事指挥，不能处处搞少数服从多数，不能老是20来人讨论来讨论去指挥作战权利必须高度集中。 3月12日，中央政治局会议讨论了教员提出的关于集中军事指挥权力的。建议并得到了一致通过， 成立了以周恩来、王稼祥和教员组成的三人军事领导小组，实际由教员进行指挥。至此，教员正式获得了红军的最高指挥权，统帅地位也得以确立。 指挥红军四渡赤水，巧渡金沙江，强渡大渡河，飞夺泸定桥，爬雪山，过草地，终于到达了陕北革命根据地，取得了长征的最后胜利。 在前后8年时间的蒙冤中被严重打击，数次的教育终于证明了自己思想的正确性，还团结了能团结的所有人，最终让全党接受了伟人的思想。教员的心胸有多伟大， 团结能力有多强。在1931年，王明和博古夺走了教员的军权，近乎于把他一撸到底。后来王明去了苏联，国内事务由博古实际指挥，从各种途径压制他， 他最终证明自己的正确，以后是不是应该扳倒博古这个绊脚石呢？他并没有教员，和博古、李德等人成为了好朋友，尽一切努力去团结他。 教员在上个世纪60年代的一次谈话中提到遵义会议时，有人劝我代替博古当总书记，我说不。这样的话，斯大林就不同意了， 硬要这样搞就会弄僵的。我们在共产国际会成为不合法的了，还是要让斯大林信得过的人抛头露面。实践证明这样做是对的，实际上并不影响我的领导地位。 在长征末期，在和张国焘的斗争中，博古、李德、凯丰这些曾经反对过教员的人都坚定的站在了教员。 这一教员下令中央红军单独北上时，张国焘前敌指挥部副参谋长李特追过来用枪指向教员的时候。是李德从后面抱住了李特，保护了教员。 1937年国共合作抗日。王明回国坐飞机从苏联抵达延安，又犯了右倾主义错误，否认在抗日统一战线中红军独立自主的原则，强调一切服从统一战线。 主动把红军置于国民党军的指挥之下，放弃党的领导权，仗着共产国际的支持，任长江局书记的王明把长江局搞成了中央第二政治局， 一段时间内甚至导致教员只是出不了延安窑洞。但教员。依然保持忍耐的态度跟王明斗争，力求做到争而不破，不撕破脸皮， 给予了王明足够的尊重，并通过摆事实、讲道理获得了绝大多数人的支持，教员的指挥权和影响力从来就不是谁授予的。 而是完完全全靠着自己的努力一步步获得的冤屈和不理解，乃至于长期被冤屈和不理解。 这在教员的眼里并不算什么。1942年4月9日，新四军军长陈毅在遭到政委饶素石排挤打击时。 教员写信给陈毅，凡事忍耐，多想自己缺点，增益其所不能，照顾大局，只要不妨碍大的原则，多多原谅人家。忍耐最难，但做一个政治家，必须联系忍耐。 这点意见请你考虑。感冒宜多睡，少动多食余容面叙。很多人觉得自己只要够强够聪明，就一定可以成事儿， 但实际上，哪怕强如伟人，人生也不可能是一帆风顺的。被自己视为战友的人，对自己各种反对和不理解，长期的被打压，被闲置， 这样的事儿，伟人当年遭遇了8年以上。碰到这样的情况，有的人选择是怨天尤人，埋怨自己遭受的不公平，从此一蹶不振。 个别人甚至另立山头儿，走向反面，而有的人选择是对同志们说需要我的时候儿打个招呼。不同的选择最终带来了不同的人生结局，最终带领我们走到了国庆节这一天。</p><h2 id="重大事件" tabindex="-1">重大事件 <a class="header-anchor" href="#重大事件" aria-label="Permalink to &quot;重大事件&quot;">​</a></h2><p>红军长征 四渡赤水 三大战役总指挥</p><h2 id="重大成果" tabindex="-1">重大成果 <a class="header-anchor" href="#重大成果" aria-label="Permalink to &quot;重大成果&quot;">​</a></h2><ul><li>1958年中国第一台黑白电视机研制成功</li><li>1958年我国第一台电子计算机诞生</li><li>1958年7000千瓦研究性重水反应堆建成</li><li>1960年歼-6批量生产</li><li>1964年10月16日我国在西北地区成功爆 炸了第一颗原子弹，爆炸当量2万吨级</li><li>1965年我国自行设计Algol型编译系统问世</li><li>1965年人工合成牛胰岛素诞生</li><li>1965年65型接触式光刻机研制成功</li><li>1965年强-5首飞</li><li>1966年歼-7首飞</li><li>1967年6月17日我国在西北地区成功爆炸了第一颗氢弹，爆炸当量为百万吨级</li><li>1967年441-B晶体管通用电子计算机研制成功</li><li>1969年双水内冷式汽轮发动机研制成功</li><li>1969年大型煤气化熔炉研制成功</li><li>1970年第一艘核潜艇“长征一号”下水</li><li>1970年4月24日东方红1号人造卫星发射成功</li><li>1971年DF-5洲际导弹试射成功</li><li>1971年第一艘导弹驱逐舰下水</li><li>1972年第一颗实用新型氢弹爆炸成功</li><li>1972年2万吨级货轮“长风号”下水</li><li>1973年集成电路计算机150研制成功</li><li>1973年首株杂交水稻培育成功</li></ul><h2 id="土地改革" tabindex="-1">土地改革 <a class="header-anchor" href="#土地改革" aria-label="Permalink to &quot;土地改革&quot;">​</a></h2><p>1952年的土地改革是中国农村经济发展中的一项重大政策，旨在通过没收地主的土地并将其分配给无地或少地的农民，来实现土地的再分配。这个过程使得广大农民获得了土地的使用权。</p><p>然而，在1958年启动的人民公社运动中，土地的管理和使用方式发生了变化。人民公社的建立使得农民的土地被集中起来，转变为集体所有，农民不再直接拥有土地的使用权，而是作为集体的一部分进行农业生产。尽管这在一定程度上提高了农业的组织化和机械化程度，但也导致了生产力的下降和农民的生活水平受到影响，最终在一定范围内遭到批评和调整。</p><p>因此，可以说，人民公社的做法是将土地的分配权再次收回，转化为集体的所有。随着后来的改革开放，特别是在1980年代的农村改革中，土地的使用权重新回到了农民手中，实行了家庭联产承包责任制，标志着农村经济政策的又一次重大转变。 在1980年之后，中国农村改革的关键措施之一是“包产到户”，这是指将土地的使用权分配给农民，农民根据自己的实际产量向国家交纳一定的公粮。 自2006年起，我国正式废除了农业税，这也包括了公粮的交纳。</p><h2 id="重大战役" tabindex="-1">重大战役 <a class="header-anchor" href="#重大战役" aria-label="Permalink to &quot;重大战役&quot;">​</a></h2><p>1946年6月26日蒋介石公然撕毁和平协议，发动了全面内战，由郑州绥靖公署主任刘峙指挥22万兵力进攻中原部队，军令原文：“48小时全歼李先念中原军区部队！”</p><h3 id="辽沈战役" tabindex="-1">辽沈战役 <a class="header-anchor" href="#辽沈战役" aria-label="Permalink to &quot;辽沈战役&quot;">​</a></h3><ul><li>时间：1948年9月12日 至 1948年11月2日</li><li>地点：今辽宁省、吉林省</li><li>参战方兵力：中国人民解放军：60万，国民党军：80万</li><li>伤亡情况：辽沈战役历时52天，人民解放军伤亡6.9万人，歼敌47.2万</li><li>主要指挥官： 林彪、罗荣桓、刘亚楼;卫立煌、廖耀湘、‌杜聿明、‌陈诚、‌范汉杰、‌郑洞国</li><li>结果：战役结束后，中国人民解放军首次在兵力数量方面超越国民党军队，解放了东北全境。</li></ul><h3 id="淮海战役" tabindex="-1">淮海战役 <a class="header-anchor" href="#淮海战役" aria-label="Permalink to &quot;淮海战役&quot;">​</a></h3><ul><li>时间：1948年11月6日至1949年1月10日</li><li>地点：淮海地区</li><li>主要战役: 陈官庄战役、双堆集战役、碾庄战役</li><li>参战方兵力：中国人民解放军：60万，国民党军：80万</li><li>伤亡情况：中国人民解放军：伤亡十余万；国民党军：伤亡及被俘55万余</li><li>主要指挥官： 邓小平、刘伯承、陈毅、粟裕、谭震林;杜聿明、黄维、黄百韬、刘峙、邱清泉</li></ul><h3 id="平津战役" tabindex="-1">平津战役 <a class="header-anchor" href="#平津战役" aria-label="Permalink to &quot;平津战役&quot;">​</a></h3><ul><li>时间：1948年11月29日至1949年1月31日</li><li>地点：北平（北京）、天津一带</li><li>参战方兵力：中国人民解放军 100万人，国民党军 52万人</li><li>伤亡情况：人民解放军 伤亡3.9万人；歼灭和改编国民党军一个战略集团52万余人</li><li>主要指挥官： 林彪、罗荣桓、聂荣臻; 傅作义、郭景云</li><li>结 果: 基本上解放了华北全境</li></ul><h3 id="渡江战役" tabindex="-1">渡江战役 <a class="header-anchor" href="#渡江战役" aria-label="Permalink to &quot;渡江战役&quot;">​</a></h3><ul><li>时间：1949年4月20日 至 1949年6月2日</li><li>地点：长江中下游</li><li>参战方兵力：中国人民解放军120万人，国民党汤恩伯部、白崇禧部共约70万人；海军2个舰队和空军4个大队</li><li>伤亡情况：中国人民解放军伤亡6万余人；中华民国国军伤亡及投降共43万余人</li><li>主要指挥官： 毛泽东、朱德、刘伯承、邓小平、粟裕；蒋介石、李宗仁、汤恩伯、白崇禧</li><li>结 果:解放江南的大部分地区，一举突破国民党军的长江防线。</li></ul><h2 id="两弹一星" tabindex="-1">两弹一星 <a class="header-anchor" href="#两弹一星" aria-label="Permalink to &quot;两弹一星&quot;">​</a></h2><p>“两弹一星”最初是指原子弹、导弹和人造卫星。“两弹”中的一弹是原子弹，后来演变为原子弹和氢弹的合称；另一弹是指导弹。“一星”则是人造地球卫星。 1955年1月15日，毛泽东召开中共中央书记处扩大会议，会议决定中国要发展原子能事业。1964年10月16日我国第一颗原子弹爆炸成功，1967年6月17日我国第一颗氢弹空爆试验成功，1970年4月24日我国第一颗人造卫星发射成功。</p><h2 id="个人崇拜" tabindex="-1">个人崇拜 <a class="header-anchor" href="#个人崇拜" aria-label="Permalink to &quot;个人崇拜&quot;">​</a></h2><p>首先，主席是反对搞个人崇拜的。（有些黑子会说主席喜欢个人崇拜，搞一言堂，立个人雕像等等来污蔑主席的话。） 有人说，崇拜是一种迷信，但是为什么会使千千万的人民而崇拜呢？话说回来，让一个人来崇拜另外一个人，简单么？ 我绝的可以说非常非常的困难，对于普通的人来说，几乎是不可能做到的事情。即便是你的孩子，你生他养他，他可以亲你，养你，但你也做不到让你的孩子崇拜你。 那么为什么会有这么多老百姓发自内心的敬爱崇拜毛主席呢，我就不用多说了吧，你现在不懂没关系，时间会给我们答案。</p><h2 id="最有力量的一段文字" tabindex="-1">最有力量的一段文字 <a class="header-anchor" href="#最有力量的一段文字" aria-label="Permalink to &quot;最有力量的一段文字&quot;">​</a></h2><p>&quot;由于我的职位低下，人们都不愿同我来往。我的职责中有一项是登记，来图书馆读报的人的姓名，可是他们大多数不把我当人看待。在那些来看报的人当中，我认出了些新文化运动的著名领导者的名字，如傅斯年、罗家伦等等，我对他们抱有强烈的兴趣。我曾经试图同他们交谈政治和文化问题，可是他们都是些大忙人，没有时间听一个图书馆助理员讲南方土话。&quot;</p><p>“但是我不因此而丧气，我仍然参加哲学研究会和新闻学研究会,想藉此能听大学里的课程。</p><p>我自己在北平的生活是十分困苦的。我家在一个叫三眼井的地方，和另外七个人合住一个小房间，我们全体挤在炕上，连呼吸的地方都没有。每逢我翻身都得预先警告身旁的人。不过在公园和故宫的宫址我看到了北国的早春，在坚冰还盖着北海的时候，我看到了怒放的梅花。北京的树木引起了我无穷的欣赏。&quot; ——教员</p><h2 id="四人帮" tabindex="-1">四人帮 <a class="header-anchor" href="#四人帮" aria-label="Permalink to &quot;四人帮&quot;">​</a></h2><p>“四人帮”是指王洪文、张春桥、江青、姚文元四人。</p><h2 id="汪东兴" tabindex="-1">汪东兴 <a class="header-anchor" href="#汪东兴" aria-label="Permalink to &quot;汪东兴&quot;">​</a></h2><p>汪东兴说 我作为多年跟随毛主席的警卫干部 接受毛主席的教育和思想很深。 这也大概就是我不能接受十 届三中全会路线以及为少奇同 志彻底平反等意见的主要原因 我的观点和思想与你们的许多 意见格格不入，彼此很难统一 在这种情况下，为了党的事业 和团结，我决定还是自已 辞职比较好。</p><h2 id="主席的诗" tabindex="-1">主席的诗 <a class="header-anchor" href="#主席的诗" aria-label="Permalink to &quot;主席的诗&quot;">​</a></h2><p>孩儿立志出乡关，学不成名誓不还。埋骨何须桑梓地，人生无处不青山。-- 出自毛泽东的《七绝·改西乡隆盛诗赠父亲》</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1910年秋天，毛泽东离开家乡韶山，走向外面更广阔的世界。这是他人生历程中的第一个转折。</span></span>
<span class="line"><span>怀着激动心情，临行前他写下这首诗，夹在父亲每天必看的帐簿里，以作告别。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>意思：孩儿立下志向走出家乡，学习不取得成就发誓不还来。死后埋葬何必在故乡的土地，人生到处都是可以埋葬尸骨的青山。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div>`,51),n=[r];function s(o,h,p,d,c,u){return i(),l("div",null,n)}const m=a(t,[["render",s]]);export{q as __pageData,m as default};
